exercise.solution:
def lire_requete(row):
    if not isinstance(row,dict) or set(row)!={'task'} or not isinstance(row['task'],str) or not 1<=len(row['task'].strip())<=4000:raise ValueError('requête invalide')
    return row['task'].strip()

exercise.check:
assert lire_requete({'task':'  tester '})=='tester'
for row in [{'task':''},{'task':'x','allow_write':True},{'task':4}]:
    try:lire_requete(row)
    except ValueError:pass
    else:raise AssertionError('requête invalide acceptée')
